import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'viewer',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('svc-reporter', 'reporter@corp.internal', 'viewer', 'sk-rpt-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def authenticate():
    key = request.headers.get('X-API-Key')
    if not key:
        return jsonify({'error': 'missing api key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (key,)).fetchone()
    if not user:
        return jsonify({'error': 'invalid api key'}), 403
    g.current_user = dict(user)

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching.
    Used by the internal dashboard for user lookup.
    """
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent schema enumeration
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid search field'}), 400

    # Build query - field is validated above so safe to interpolate
    # Value uses LIKE for partial matching
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        # Log the search action
        db.execute(
            'INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
            ('user_search', g.current_user['username'], f'{field}:{value}')
        )
        db.commit()
        return jsonify({'results': [dict(r) for r in results]})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v1/users/<username>/promote', methods=['POST'])
def promote_user(username):
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'admin required'}), 403
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE username = ?', ('admin', username))
    db.commit()
    return jsonify({'status': 'promoted'})

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': os.getenv('APP_VERSION', 'dev')})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000, debug=False)
